pattern=re.compile(r"function statistics\(\)\{.*?\nfunction explicitPermissionCount",re.S)
replacement=r'''function statUid(x){return String(x?.uid||x?.id||'')}
function statisticsRows(){
  const own=statUid(window.AKTIF_KULLANICI||window.AppStore?.get?.('session.user')),rawStats=arr('kullaniciIstatistikleri'),statsByUid=new Map(rawStats.map(x=>[statUid(x),x]).filter(x=>x[0])),allUsers=arr('kullanicilar'),users=admin()?allUsers:allUsers.filter(u=>statUid(u)===own),seen=new Set(),rows=[];
  for(const u of users){const uid=statUid(u);if(!uid)continue;const stat=statsByUid.get(uid)||null;seen.add(uid);rows.push({...((stat)||{}),id:uid,uid,__user:u,__hasStats:!!stat})}
  if(admin()){for(const stat of rawStats){const uid=statUid(stat);if(!uid||seen.has(uid))continue;rows.push({...stat,id:uid,uid,__user:null,__hasStats:true,__orphan:true})}}
  else if(!rows.length&&own&&statsByUid.has(own)){const stat=statsByUid.get(own);rows.push({...stat,id:own,uid:own,__user:null,__hasStats:true})}
  return rows.sort((a,b)=>Number(b.girisSayisi||0)-Number(a.girisSayisi||0)||String(userName(a.__user||a)||'').localeCompare(String(userName(b.__user||b)||''),'tr',{sensitivity:'base'}))
}
async function prepareStatisticsData(force=false){
  if(statisticsRefreshing)return;statisticsRefreshing=true;if(mounted&&active==='statistics')render();
  try{
    if(window.SyncEngine&&window.COL?.kullanicilar){window.SyncEngine.register('kullanicilar',COL.kullanicilar);await window.SyncEngine.localHydrate(['kullanicilar']);if(navigator.onLine)await window.SyncEngine.pull(['kullanicilar'])}
    if(window.IstatistikService?.prepare){await window.IstatistikService.prepare(admin());if(admin())await window.IstatistikService.prepare(true)}
    if(force&&navigator.onLine&&window.SyncEngine)await window.SyncEngine.pull(['kullaniciIstatistikleri'])
  }catch(e){console.warn('[Kullanıcı İstatistikleri]',e?.message||e)}finally{statisticsRefreshing=false;if(mounted&&active==='statistics')render()}
}
function statisticsIdentity(row){const u=row.__user||{},photo=userPhoto(u),name=row.ad||userName(u)||u.email||'Bilinmeyen kullanıcı',handle=u.kullaniciAdi?`@${u.kullaniciAdi}`:(u.email||''),role=u.id||u.uid?userRole(u):(row.__orphan?'Silinmiş hesap':'Kullanıcı'),initials=userInitials(u)||String(name).trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toLocaleUpperCase('tr')||'K';return{u,photo,name,handle,role,initials}}
function statistics(){
  const rows=statisticsRows(),accounts=rows.filter(x=>x.__user).length,activeUsers=rows.filter(x=>x.__user&&x.__user.aktif!==false).length,tracked=rows.filter(x=>x.__hasStats).length,totals={login:rows.reduce((n,x)=>n+Number(x.girisSayisi||0),0),time:rows.reduce((n,x)=>n+Number(x.toplamSureSaniye||0),0),files:rows.reduce((n,x)=>n+Number(x.dosyaYuklemeSayisi||0),0)},summary=[['👥','Hesaplar',accounts],['↪','Toplam Giriş',totals.login],['◷','Kullanım',duration(totals.time)],['⇧','Dosya',totals.files]];
  return `<section class="ka-statistics-page"><header class="ka-statistics-hero"><div class="ka-statistics-hero__mark" aria-hidden="true">▥</div><div class="ka-statistics-hero__copy"><span>${admin()?'YÖNETİCİ GÖRÜNÜMÜ':'KİŞİSEL ANALİTİK'}</span><h3>Kullanıcı Analitiği</h3><p>${admin()?`${accounts} hesap · ${activeUsers} aktif · ${tracked} istatistik kaydı`:'Kendi kullanım hareketlerinizi görüntülüyorsunuz.'}</p></div><button type="button" class="ka-statistics-refresh" data-stat-refresh ${statisticsRefreshing?'disabled':''} aria-label="İstatistikleri yenile">${statisticsRefreshing?'…':'↻'}</button></header><div class="ka-statistics-summary">${summary.map(([icon,label,value])=>`<article><span aria-hidden="true">${icon}</span><div><small>${label}</small><strong>${esc(value)}</strong></div></article>`).join('')}</div><div class="ka-statistics-list-head"><div><strong>${admin()?'Tüm Kullanıcılar':'Kullanım Özeti'}</strong><small>${admin()?'İstatistik kaydı olmayan hesaplar da listelenir.':'Hesabınıza ait güncel kullanım verileri.'}</small></div><b>${accounts} hesap</b></div><div class="ka-statistics-users">${rows.length?rows.map((s,i)=>{const d=s.depolamaKullanimi||{},id=statUid(s),{u,photo,name,handle,role,initials}=statisticsIdentity(s),muaf=!!u.depolamaMuaf,last=s.sonGiris?statDate(s.sonGiris):'Henüz giriş yapmadı',status=u.id||u.uid?(u.aktif===false?'Pasif':'Aktif'):(s.__orphan?'Hesap silinmiş':'Kayıt yok');return `<article class="ka-statistics-user ${s.__hasStats?'':'is-untracked'}"><header class="ka-statistics-user__head"><span class="ka-statistics-user__avatar">${photo?`<img src="${esc(photo)}" alt="">`:esc(initials)}</span><div class="ka-statistics-user__identity"><div class="ka-statistics-user__name"><strong>${esc(name)}</strong>${u.admin?'<b class="ka-statistics-badge is-admin">Admin</b>':''}</div><small>${esc([handle,role].filter(Boolean).join(' · '))}</small><span class="ka-statistics-last ${s.sonGiris?'':'is-empty'}">${s.sonGiris?'Son giriş: ':''}${esc(last)}</span></div><span class="ka-statistics-rank">${s.__hasStats?`#${i+1}`:'Yeni'}</span></header><div class="ka-statistics-metrics"><div><small>Giriş</small><strong>${Number(s.girisSayisi||0)}</strong></div><div><small>Kullanım</small><strong>${esc(duration(s.toplamSureSaniye))}</strong></div><div><small>Dosya</small><strong>${Number(s.dosyaYuklemeSayisi||0)}</strong></div><div><small>Not</small><strong>${Number(s.notEklemeSayisi||0)}</strong></div></div><div class="ka-statistics-user__meta"><span><b>En çok kullanılan</b>${esc(topPage(s.sayfaZiyaretleri))}</span><span class="ka-statistics-badge ${status==='Aktif'?'is-active':status==='Pasif'?'is-passive':'is-neutral'}">${esc(status)}</span></div><details class="ka-statistics-storage"><summary><span><b>Depolama</b><small>Mesaj, duyuru, doküman ve takvim</small></span><strong>${esc(mb(totalStorage(s)))}</strong><i aria-hidden="true">›</i></summary><div class="ka-statistics-storage__body">${[['Mesaj','mesaj'],['Duyuru','duyuru'],['Doküman','dokuman'],['Takvim','takvim']].map(([label,key])=>`<div><span>${label}</span><strong>${esc(mb(d[key]))}</strong></div>`).join('')}${u.id||u.uid?`<label class="ka-statistics-exempt"><input type="checkbox" data-stat-exempt="${esc(id)}" ${muaf?'checked':''} ${canUsers('edit')?'':'disabled'}><span><b>Depolama sınırından muaf</b><small>Bu kullanıcı için yükleme kotasını uygulama.</small></span></label>`:''}</div></details></article>`}).join(''):'<div class="ka-statistics-empty"><span>👥</span><strong>Kullanıcı hesabı bulunamadı</strong><small>Kullanıcı kayıtları senkronlandığında burada görünecek.</small></div>'}</div></section>`
}
function bindStatistics(out){out.querySelector('[data-stat-refresh]')?.addEventListener('click',()=>prepareStatisticsData(true));out.querySelectorAll('[data-stat-exempt]:not([disabled])').forEach(ch=>ch.onchange=async()=>{const val=ch.checked;ch.disabled=true;try{await window.KullaniciIstatistikleriService.kullaniciMuafiyetKaydet(ch.dataset.statExempt,val);toast?.(val?'Kullanıcı depolama sınırından muaf tutuldu.':'Depolama muafiyeti kaldırıldı.')}catch(e){ch.checked=!val;toast?.('Muafiyet güncellenemedi: '+(e?.message||e))}finally{ch.disabled=false}})}
function explicitPermissionCount'''
s,count=pattern.subn(lambda m:replacement,s,count=1)
if count!=1: raise SystemExit(f'statistics block replacement count={count}')

old_open="""function openPage(page,title=''){if(!activeAllowed(page)){window.toast?.('Bu ayar sayfası için yetkiniz yok.');return false}active=page;const h=document.querySelector('[data-settings-module] h2');if(h)h.textContent=page==='home'?'Ayarlar':(title||h.textContent);render();return true}"""
new_open="""function openPage(page,title=''){if(!activeAllowed(page)){window.toast?.('Bu ayar sayfası için yetkiniz yok.');return false}active=page;const h=document.querySelector('[data-settings-module] h2'),desc=document.querySelector('[data-settings-description]');if(h)h.textContent=page==='home'?'Ayarlar':(title||h.textContent);if(desc)desc.textContent=settingsDescription(page);render();if(page==='statistics')void prepareStatisticsData(false);return true}"""
